import{_ as o,o as a,c as r,a5 as s}from"./chunks/framework.Bt0SrEfo.js";const h=JSON.parse('{"title":"面试自我介绍模板","description":"","frontmatter":{},"headers":[],"relativePath":"面试/3-自我介绍.md","filePath":"面试/3-自我介绍.md","lastUpdated":1789788214000}'),n={name:"面试/3-自我介绍.md"};function e(l,t,i,u,g,p){return a(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="面试自我介绍模板" tabindex="-1">面试自我介绍模板 <a class="header-anchor" href="#面试自我介绍模板" aria-label="Permalink to &quot;面试自我介绍模板&quot;">​</a></h1><blockquote><p><strong>使用场景</strong>：面试开场 1-5 分钟的自我介绍，决定第一印象和后续问题走向。</p><p><strong>核心原则</strong>：</p><ul><li>✅ <strong>公式</strong>：基本信息 + 技术栈 + 代表项目 + 核心能力 + 求职动机</li><li>✅ <strong>3 个版本</strong>：1 分钟（HR）/ 3 分钟（技术面，最常用）/ 5 分钟（终面）</li><li>✅ <strong>讲故事</strong>：不要背简历，讲&quot;我做了什么 + 怎么做的 + 带来什么价值&quot;</li></ul></blockquote><hr><h2 id="一、自介绍万能公式" tabindex="-1">一、自介绍万能公式 <a class="header-anchor" href="#一、自介绍万能公式" aria-label="Permalink to &quot;一、自介绍万能公式&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[基本信息]   你好，我叫 XXX，X 年前端经验，主要做 XXX 方向。</span></span>
<span class="line"><span>    +</span></span>
<span class="line"><span>[技术栈]     主力技术栈是 React/Vue + TypeScript + Webpack/Vite。</span></span>
<span class="line"><span>    +</span></span>
<span class="line"><span>[代表项目]   最近做过的最有挑战的项目是 XXX，我在其中负责 XXX、主导了 XXX。</span></span>
<span class="line"><span>    +</span></span>
<span class="line"><span>[核心能力]   我比较擅长 XXX（比如性能优化 / 工程化建设 / 跨端开发）。</span></span>
<span class="line"><span>    +</span></span>
<span class="line"><span>[求职动机]   这次看新机会主要是因为 XXX（业务 / 技术成长 / 团队）。</span></span></code></pre></div><hr><h2 id="二、3-个版本" tabindex="-1">二、3 个版本 <a class="header-anchor" href="#二、3-个版本" aria-label="Permalink to &quot;二、3 个版本&quot;">​</a></h2><h3 id="🔥-1-分钟版-电梯版-破冰用" tabindex="-1">🔥 1 分钟版（电梯版 / 破冰用） <a class="header-anchor" href="#🔥-1-分钟版-电梯版-破冰用" aria-label="Permalink to &quot;🔥 1 分钟版（电梯版 / 破冰用）&quot;">​</a></h3><h4 id="✅-推荐版-7-年经验-已实战优化" tabindex="-1">✅ 推荐版（7 年经验 / 已实战优化） <a class="header-anchor" href="#✅-推荐版-7-年经验-已实战优化" aria-label="Permalink to &quot;✅ 推荐版（7 年经验 / 已实战优化）&quot;">​</a></h4><blockquote><p>&quot;面试官你好，我叫 <strong>XXX</strong>，<strong>7 年</strong>前端经验，做过 <strong>B 端 SaaS、SSR、PWA、跨端 App 和大屏</strong>这些方向。</p><p><strong>技术栈</strong>上主力是 <strong>React + TypeScript + Next.js</strong>，最近 2 年主导了好几个中后台项目；同时熟悉 <strong>Vue 生态</strong>（Vue 2/3 + Vite），去年刚主导过一个 <strong>Vue 2 + Webpack 4 迁移到 Vue 3 + Vite + Pinia</strong> 的项目，<strong>80 多个组件，启动时间 28 秒降到 0.8 秒</strong>；移动端用 uni-app 做过跨端 App + IoT 大屏。</p><p><strong>我比较擅长</strong>性能优化和工程化建设，能从源码层面讲清楚 Webpack Loader/Plugin 链、Vite 的 esbuild 预构建原理。</p><p>这次想找一个<strong>业务更聚焦、有技术挑战</strong>的方向。&quot;</p></blockquote><p>⏱️ 约 60 秒 ｜ 字数 ~260 字</p><p><strong>亮点拆解</strong>：</p><ul><li>✅ <strong>方向 + 技术栈分层</strong>：先说做过哪些方向（业务广度），再分层说技术栈（主力 / 同时熟悉 / 移动端）</li><li>✅ <strong>具体项目 + 数据化</strong>：80 多个组件、28 秒 → 0.8 秒（不是&quot;做了性能优化&quot;）</li><li>✅ <strong>能力标签收尾</strong>：性能优化和工程化建设 + 源码层理解</li><li>✅ <strong>钩子引导追问</strong>：&quot;业务更聚焦、有技术挑战&quot; → 面试官可能问业务 / 技术细节</li></ul><hr><h4 id="备选版-hr-面-笔试破冰" tabindex="-1">备选版（HR 面 / 笔试破冰） <a class="header-anchor" href="#备选版-hr-面-笔试破冰" aria-label="Permalink to &quot;备选版（HR 面 / 笔试破冰）&quot;">​</a></h4><blockquote><p>&quot;你好，我叫 <strong>XXX</strong>，<strong>7 年</strong>前端经验，主要做 <strong>B 端 SaaS 和中后台系统</strong>。</p><p>主力技术栈是 <strong>React + TypeScript + Next.js</strong>，最近一个项目是 <strong>XX</strong>，从 0 到 1 主导完成了整体架构和核心模块。</p><p>同时也熟悉 <strong>Vue 生态</strong>，去年主导过一个 Vue 2 到 Vue 3 + Vite 的迁移项目，启动速度从 28 秒降到 0.8 秒。</p><p>平时对<strong>前端工程化</strong>和<strong>性能优化</strong>比较感兴趣，这次看新机会主要是因为业务方向比较契合。&quot;</p></blockquote><p><strong>适用</strong>：</p><ul><li>HR 面试</li><li>笔试前的破冰</li><li>终面一开始的&quot;介绍下自己&quot;</li></ul><p><strong>要点</strong>：</p><ul><li>控制在 <strong>200-300 字</strong> / <strong>45-60 秒</strong></li><li>一句话说清楚<strong>几个关键标签</strong>：年限 + 技术栈 + 1 个亮点项目</li><li>末句留钩子（&quot;对前端工程化感兴趣&quot;），引导面试官追问</li></ul><hr><h3 id="⭐-3-分钟版-标准版-技术面最常用" tabindex="-1">⭐ 3 分钟版（标准版 / 技术面最常用） <a class="header-anchor" href="#⭐-3-分钟版-标准版-技术面最常用" aria-label="Permalink to &quot;⭐ 3 分钟版（标准版 / 技术面最常用）&quot;">​</a></h3><blockquote><p>&quot;你好，我叫 <strong>XXX</strong>，<strong>X 年</strong>前端经验，目前在 <strong>XX 公司</strong>做 <strong>B 端运营 SaaS</strong>。</p><p><strong>技术栈</strong>：主力是 <strong>React + TypeScript + Next.js</strong>，做过 SSR 和 PWA；同时熟悉 Vue 生态（Vue 2 / Vue 3 + Pinia / Vite），有完整迁移经验；移动端用过 uni-app，跨端方案比较熟。</p><p><strong>最近的项目</strong>是商户管理 SaaS 平台，模块比较多（10+ 业务模块），我作为前端核心开发，主要做了三件事：</p><p><strong>第一</strong>，沉淀了一套<strong>可复用的中后台组件库</strong>——可配置表格、搜索表单、弹窗表单、权限按钮、金额输入等。后续新模块的开发效率提升了 40% 左右。</p><p><strong>第二</strong>，搭建了<strong>统一的接口请求层</strong>，基于 swagger-typescript-api 自动生成类型和请求方法，集中处理 Token、错误码、多环境切换和重复请求拦截。</p><p><strong>第三</strong>，配合业务做了<strong>金额处理的安全加固</strong>，区分法币和虚拟币精度，处理 RSA 加密登录、富文本 XSS 防护等安全细节。</p><p><strong>另一个想讲的</strong>项目是智能风控引擎平台。这个项目是我从老同事手里接过来的 Vue 2 + Webpack 4 项目，我主导做了<strong>整体迁移到 Vue 3 + Vite + Pinia</strong>。这个迁移我印象很深，因为涉及到：</p><ul><li>80 多个组件的 Composition API 重构（主要是 mixin 拆分）</li><li>第三方库的 ESM 兼容处理</li><li>用 <code>shallowRef</code> 优化大列表渲染</li><li>最终启动时间从 28s 降到 0.8s，但包体没明显变小（因为业务代码量大）</li></ul><p><strong>我比较擅长</strong>的事情是<strong>性能优化和工程化建设</strong>，对前端构建工具（Webpack / Vite / Rollup）和监控体系也比较熟悉。</p><p>这次看新机会主要是想找一个<strong>业务方向更聚焦、技术挑战更大的平台</strong>。&quot;</p></blockquote><p><strong>适用</strong>：70% 技术面试，各种 level 都通用</p><p><strong>要点</strong>：</p><ul><li><strong>300-500 字</strong> / <strong>2-3 分钟</strong></li><li>选 <strong>2 个项目</strong>展开（不要贪多）</li><li>每个项目讲 <strong>1-2 个具体亮点</strong>（最好有数据）</li><li>用<strong>技术名词</strong>展示深度，但不念列表</li></ul><hr><h3 id="🎯-5-分钟版-深度版-终面-高-level-面试" tabindex="-1">🎯 5 分钟版（深度版 / 终面 / 高 level 面试） <a class="header-anchor" href="#🎯-5-分钟版-深度版-终面-高-level-面试" aria-label="Permalink to &quot;🎯 5 分钟版（深度版 / 终面 / 高 level 面试）&quot;">​</a></h3><blockquote><p>&quot;你好，我叫 <strong>XXX</strong>，<strong>X 年</strong>前端经验，目前在 <strong>XX 公司</strong>。</p><p>我自己的技术成长大致分三个阶段：</p><p><strong>第一阶段（0-2 年）：基础建设期</strong>。这一段主要在做业务页面、组件库沉淀、熟悉框架原理。我从 Vue 2 学起，后来切到 React，主要靠项目驱动 + 读源码 + 写技术博客沉淀。</p><p><strong>第二阶段（2-4 年）：复杂业务 + 工程化</strong>。这一段开始做中大型项目。我做过的几个有代表性的：</p><ul><li><p><strong>商户管理 SaaS 平台</strong>（React + Next.js，团队 X 人）：这个项目业务复杂度比较高（10+ 模块），我作为前端核心负责两块：</p><ul><li>一是<strong>接口契约 + 统一请求层</strong>，通过 <code>swagger-typescript-api</code> 自动生成 TS 类型和请求方法，配合 Axios 拦截器做 Token 刷新、错误码处理、请求去重（特别是登录失效时的并发请求控制，用了 refresh token 单例队列）</li><li>二是<strong>复杂业务组件抽象</strong>，比如金额输入组件（区分法币和虚拟币的精度）、权限按钮、可配置表格</li></ul></li><li><p><strong>会员 Web / H5</strong>（Vue 2 + SSR + PWA）：这个项目技术栈比较杂，包含 SSR、PWA、三方登录。我做了三块：</p><ul><li>用 FingerprintJS 做设备指纹</li><li>验证码单例管理器（多请求并发只弹一次）</li><li>iframe URL 白名单校验（防钓鱼）</li></ul></li></ul><p><strong>第三阶段（4-5 年）：架构能力 + 跨端</strong>。这一段开始主导迁移项目和跨端方案。</p><ul><li><p><strong>智能风控平台</strong>（Vue 2 → Vue 3 + Vite 迁移）：这个项目是我主导的。80 多个组件，从 mixin 拆分到 setup 组合式，第三方库 ESM 兼容处理，用 esbuild 预构建优化。<strong>最后启动时间从 28 秒降到 0.8 秒</strong>，HMR 从 2 秒降到 50 毫秒。但包体没明显变小，因为业务代码量大——这个发现也让我理解了 Rollup 和 Webpack 在产物层面的差异。</p></li><li><p><strong>农业数字化 App + IoT 大屏</strong>（uni-app + ECharts）：跨端 + 大屏。ECharts 异步 tooltip、地图和底部轮播联动、WebSocket 在 App 的生命周期管理。</p></li></ul><p><strong>总结一下</strong>，我自己的优势：</p><ol><li><strong>业务理解</strong>：不只写页面，能从业务视角拆解需求、设计组件</li><li><strong>工程化能力</strong>：写过可复用的中间层和组件库，能独立负责一个新项目的脚手架搭建</li><li><strong>跨端经验</strong>：Web / H5 / 小程序 / 大屏都做过，能快速上手新技术</li><li><strong>学习能力</strong>：Vue 2 到 Vue 3、React 到 Next.js，每次切换都比较快</li></ol><p><strong>这次的求职动机</strong>：想找一个<strong>业务更聚焦、用户量更大、有技术挑战的平台</strong>。如果有<strong>带人 / 主导项目</strong>的机会会更感兴趣。&quot;</p></blockquote><p><strong>适用</strong>：</p><ul><li>终面 / CTO 面</li><li>高级以上岗位</li><li>面试官明显想听完整故事</li></ul><p><strong>要点</strong>：</p><ul><li><strong>600-900 字</strong> / <strong>4-5 分钟</strong></li><li><strong>分阶段讲成长</strong>（比按项目讲更显思考）</li><li>突出<strong>主导</strong>和<strong>数据</strong></li><li>末段总结能力 + 求职动机</li></ul><hr><h2 id="三、4-个项目怎么选-怎么讲" tabindex="-1">三、4 个项目怎么选 / 怎么讲 <a class="header-anchor" href="#三、4-个项目怎么选-怎么讲" aria-label="Permalink to &quot;三、4 个项目怎么选 / 怎么讲&quot;">​</a></h2><h3 id="选项目的优先级" tabindex="-1">选项目的优先级 <a class="header-anchor" href="#选项目的优先级" aria-label="Permalink to &quot;选项目的优先级&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>按&quot;和目标岗位匹配度&quot;选：</span></span>
<span class="line"><span>  业务复杂度高 + 技术栈匹配 + 有数据 → 必讲</span></span>
<span class="line"><span>  业务复杂度中等 + 技术栈匹配     → 选讲</span></span>
<span class="line"><span>  业务简单 或 技术栈不匹配        → 一句话带过</span></span></code></pre></div><h3 id="_4-个项目的-标签" tabindex="-1">4 个项目的&quot;标签&quot; <a class="header-anchor" href="#_4-个项目的-标签" aria-label="Permalink to &quot;4 个项目的&quot;标签&quot;&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>一句话标签</th><th>适合的场景</th></tr></thead><tbody><tr><td>商户管理 SaaS</td><td><strong>复杂业务 + 工程化建设</strong></td><td>80% 公司都适用，B 端公司必讲</td></tr><tr><td>会员 Web / H5</td><td><strong>SSR + PWA + 三方登录</strong></td><td>涉及 SSR / 移动端 / 海外业务的公司</td></tr><tr><td>智能风控平台</td><td><strong>Vue 2 → 3 + Vite 迁移</strong></td><td>Vue 技术栈公司、看重工程化的公司</td></tr><tr><td>农业数字化</td><td><strong>跨端 + 大屏</strong></td><td>物联网 / 大数据 / ToG 公司</td></tr></tbody></table><h3 id="每个项目的-30-秒介绍-模板" tabindex="-1">每个项目的&quot;30 秒介绍&quot;模板 <a class="header-anchor" href="#每个项目的-30-秒介绍-模板" aria-label="Permalink to &quot;每个项目的&quot;30 秒介绍&quot;模板&quot;">​</a></h3><h4 id="商户管理-saas-平台" tabindex="-1">商户管理 SaaS 平台 <a class="header-anchor" href="#商户管理-saas-平台" aria-label="Permalink to &quot;商户管理 SaaS 平台&quot;">​</a></h4><blockquote><p>&quot;商户管理 SaaS，<strong>React + Next.js + TS</strong>，业务复杂度比较高（10+ 模块）。我重点做了接口契约 + 统一请求层（基于 swagger-typescript-api）、可复用组件库、还有金额精度等安全加固。&quot;</p></blockquote><h4 id="会员-web-h5" tabindex="-1">会员 Web / H5 <a class="header-anchor" href="#会员-web-h5" aria-label="Permalink to &quot;会员 Web / H5&quot;">​</a></h4><blockquote><p>&quot;会员服务平台，<strong>Vue 2 + SSR + PWA</strong>。我负责三件事：FingerprintJS 设备指纹、验证码单例管理器（多请求并发只弹一次）、iframe URL 白名单防钓鱼。&quot;</p></blockquote><h4 id="智能风控平台" tabindex="-1">智能风控平台 <a class="header-anchor" href="#智能风控平台" aria-label="Permalink to &quot;智能风控平台&quot;">​</a></h4><blockquote><p>&quot;智能风控引擎平台，<strong>Vue 2 + Webpack 4</strong> 起手，我主导迁移到 <strong>Vue 3 + Vite + Pinia</strong>。80+ 组件 Composition API 重构，启动时间 28s → 0.8s，HMR 2s → 50ms。&quot;</p></blockquote><h4 id="农业数字化-app-iot-大屏" tabindex="-1">农业数字化 App + IoT 大屏 <a class="header-anchor" href="#农业数字化-app-iot-大屏" aria-label="Permalink to &quot;农业数字化 App + IoT 大屏&quot;">​</a></h4><blockquote><p>&quot;农业数字化，<strong>uni-app + ECharts</strong>，跨端 App + IoT 大屏。我做了 WebSocket 即时通讯、ECharts 异步 tooltip、地图和底部轮播联动。&quot;</p></blockquote><hr><h2 id="四、为什么看新机会-最容易踩雷的题" tabindex="-1">四、为什么看新机会（最容易踩雷的题） <a class="header-anchor" href="#四、为什么看新机会-最容易踩雷的题" aria-label="Permalink to &quot;四、为什么看新机会（最容易踩雷的题）&quot;">​</a></h2><h3 id="万能公式" tabindex="-1">万能公式 <a class="header-anchor" href="#万能公式" aria-label="Permalink to &quot;万能公式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[对现公司真实不满] + [目标岗位吸引点]</span></span></code></pre></div><h3 id="_5-个参考话术-根据实际情况选" tabindex="-1">5 个参考话术（根据实际情况选） <a class="header-anchor" href="#_5-个参考话术-根据实际情况选" aria-label="Permalink to &quot;5 个参考话术（根据实际情况选）&quot;">​</a></h3><h4 id="话术-a-业务方向" tabindex="-1">话术 A：业务方向 <a class="header-anchor" href="#话术-a-业务方向" aria-label="Permalink to &quot;话术 A：业务方向&quot;">​</a></h4><blockquote><p>&quot;现在公司业务方向有些调整，新项目不太能发挥我的经验。我比较想找一个<strong>业务更聚焦、用户量更大</strong>的平台。&quot;</p></blockquote><h4 id="话术-b-技术成长" tabindex="-1">话术 B：技术成长 <a class="header-anchor" href="#话术-b-技术成长" aria-label="Permalink to &quot;话术 B：技术成长&quot;">​</a></h4><blockquote><p>&quot;现在公司技术栈相对稳定了（Vue 2 老项目维护为主），我想找一个<strong>技术更新迭代更快、有挑战</strong>的环境。&quot;</p></blockquote><h4 id="话术-c-职业发展" tabindex="-1">话术 C：职业发展 <a class="header-anchor" href="#话术-c-职业发展" aria-label="Permalink to &quot;话术 C：职业发展&quot;">​</a></h4><blockquote><p>&quot;目前团队规模比较小，<strong>主导机会有限</strong>。希望去一个<strong>更大的平台</strong>，能带团队、主导更大的项目。&quot;</p></blockquote><h4 id="话术-d-业务-行业" tabindex="-1">话术 D：业务/行业 <a class="header-anchor" href="#话术-d-业务-行业" aria-label="Permalink to &quot;话术 D：业务/行业&quot;">​</a></h4><blockquote><p>&quot;现公司业务比较窄（主要是 XX），我想<strong>拓展行业经验</strong>，比如对贵公司的 XX 业务方向（金融/电商/SaaS）很感兴趣。&quot;</p></blockquote><h4 id="话术-e-异地-家庭" tabindex="-1">话术 E：异地/家庭 <a class="header-anchor" href="#话术-e-异地-家庭" aria-label="Permalink to &quot;话术 E：异地/家庭&quot;">​</a></h4><blockquote><p>&quot;家庭原因计划<strong>换城市发展</strong> / 通勤距离想缩短，对贵公司的<strong>位置</strong>比较满意。&quot;</p></blockquote><h3 id="❌-不要说的话" tabindex="-1">❌ 不要说的话 <a class="header-anchor" href="#❌-不要说的话" aria-label="Permalink to &quot;❌ 不要说的话&quot;">​</a></h3><ul><li>❌ &quot;现公司领导不行 / 同事太差 / 加班太多&quot;</li><li>❌ &quot;薪资太低&quot;</li><li>❌ &quot;被裁员 / 公司倒闭&quot;</li><li>❌ &quot;想躺平&quot;</li><li>❌ 任何对前雇主的负面评价</li></ul><hr><h2 id="五、自我介绍常见误区" tabindex="-1">五、自我介绍常见误区 <a class="header-anchor" href="#五、自我介绍常见误区" aria-label="Permalink to &quot;五、自我介绍常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>反例</th><th>改法</th></tr></thead><tbody><tr><td><strong>念简历</strong></td><td>&quot;我叫 XXX，2020 年毕业于 XX 大学，在 XX 公司担任 XXX...&quot;</td><td>讲故事，跳过基础信息</td></tr><tr><td><strong>技术栈罗列</strong></td><td>&quot;我熟悉 React、Vue、Angular、Webpack、Vite、Rollup...&quot;</td><td>一句话带过主力技术栈</td></tr><tr><td><strong>流水账</strong></td><td>项目 1 干了 A，项目 2 干了 B...</td><td>选 1-2 个项目讲亮点</td></tr><tr><td><strong>没有数据</strong></td><td>&quot;我做了性能优化&quot;</td><td>&quot;<strong>启动时间从 28s 降到 0.8s</strong>&quot;</td></tr><tr><td><strong>没有钩子</strong></td><td>介绍完就停下来</td><td>末句留钩子引导追问</td></tr><tr><td><strong>超时</strong></td><td>自我介绍讲 5 分钟还没完</td><td>严格控制时间，3 分钟最佳</td></tr><tr><td><strong>过于谦虚</strong></td><td>&quot;我做得不够好，能力一般...&quot;</td><td>自信表达，主动展示</td></tr></tbody></table><hr><h2 id="六、面试官听完自我介绍后的高频追问" tabindex="-1">六、面试官听完自我介绍后的高频追问 <a class="header-anchor" href="#六、面试官听完自我介绍后的高频追问" aria-label="Permalink to &quot;六、面试官听完自我介绍后的高频追问&quot;">​</a></h2><h3 id="_1-你刚才提到的-xx-项目-能具体讲讲吗" tabindex="-1">1. &quot;你刚才提到的 XX 项目，能具体讲讲吗？&quot; <a class="header-anchor" href="#_1-你刚才提到的-xx-项目-能具体讲讲吗" aria-label="Permalink to &quot;1. &quot;你刚才提到的 XX 项目，能具体讲讲吗？&quot;&quot;">​</a></h3><p>✅ 准备好每个项目的 <strong>STAR</strong>：</p><ul><li><strong>S</strong>ituation（背景）：项目什么场景，多少用户</li><li><strong>T</strong>ask（任务）：你的职责和挑战</li><li><strong>A</strong>ction（行动）：你具体做了什么</li><li><strong>R</strong>esult（结果）：数据化产出</li></ul><h3 id="_2-你刚才说-xx-这个具体怎么做的" tabindex="-1">2. &quot;你刚才说 XX，这个具体怎么做的？&quot; <a class="header-anchor" href="#_2-你刚才说-xx-这个具体怎么做的" aria-label="Permalink to &quot;2. &quot;你刚才说 XX，这个具体怎么做的？&quot;&quot;">​</a></h3><p>✅ 自我介绍里<strong>只说关键词</strong>，细节留给追问。</p><p>反例：</p><blockquote><p>❌ 我用了 swagger-typescript-api，它是一个 npm 包，可以通过 npx swagger-typescript-api -p xxx 生成 client 文件，然后 import { ... } from &#39;./api&#39;...</p></blockquote><p>正例：</p><blockquote><p>✅ 我用 swagger-typescript-api 自动生成 TS 类型和请求方法。</p></blockquote><h3 id="_3-你为什么离职" tabindex="-1">3. &quot;你为什么离职？&quot; <a class="header-anchor" href="#_3-你为什么离职" aria-label="Permalink to &quot;3. &quot;你为什么离职？&quot;&quot;">​</a></h3><p>→ 参考第四章&quot;为什么看新机会&quot;</p><h3 id="_4-你的职业规划是什么" tabindex="-1">4. &quot;你的职业规划是什么？&quot; <a class="header-anchor" href="#_4-你的职业规划是什么" aria-label="Permalink to &quot;4. &quot;你的职业规划是什么？&quot;&quot;">​</a></h3><blockquote><p>&quot;未来 1-2 年我希望<strong>深耕一个业务领域</strong>（比如 B 端 SaaS），同时<strong>带几个人</strong>做更完整的项目交付。3-5 年希望成为能<strong>主导技术选型 + 带团队</strong>的 Tech Lead。&quot;</p></blockquote><h3 id="_5-你有什么问题想问" tabindex="-1">5. &quot;你有什么问题想问？&quot; <a class="header-anchor" href="#_5-你有什么问题想问" aria-label="Permalink to &quot;5. &quot;你有什么问题想问？&quot;&quot;">​</a></h3><p>→ 看 <a href="./面试技巧/15.线下面试技巧">面试技巧</a>（如有）</p><hr><h2 id="七、面试前-5-分钟准备清单" tabindex="-1">七、面试前 5 分钟准备清单 <a class="header-anchor" href="#七、面试前-5-分钟准备清单" aria-label="Permalink to &quot;七、面试前 5 分钟准备清单&quot;">​</a></h2><ul><li>[ ] 选定要用的版本（1 / 3 / 5 分钟）</li><li>[ ] 选定要展开的 2 个项目</li><li>[ ] 每个项目准备 1-2 个<strong>数据化亮点</strong></li><li>[ ] 准备&quot;为什么看新机会&quot;的话术</li><li>[ ] 准备 1-2 个反问面试官的问题</li><li>[ ] 自我介绍要<strong>写下来</strong>（关键词就行），对着镜子说一遍，控制在目标时间内</li></ul><hr><h2 id="📌-推荐策略" tabindex="-1">📌 推荐策略 <a class="header-anchor" href="#📌-推荐策略" aria-label="Permalink to &quot;📌 推荐策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>第一次面试</th><th>用 1 分钟版（破冰），看面试官反馈再决定展开</th></tr></thead><tbody><tr><td>第二次面试（技术面）</td><td>用 <strong>3 分钟版</strong>（最通用）</td></tr><tr><td>终面 / 高 level</td><td>用 <strong>5 分钟版</strong></td></tr><tr><td>HR 面</td><td>用 <strong>1 分钟版</strong></td></tr></tbody></table><hr><h2 id="🔗-相关文档" tabindex="-1">🔗 相关文档 <a class="header-anchor" href="#🔗-相关文档" aria-label="Permalink to &quot;🔗 相关文档&quot;">​</a></h2><ul><li><a href="./">面试总览</a></li><li><a href="/面试/2-复习清单">复习清单</a></li><li><a href="./项目/项目经验/">4 个项目经验</a></li></ul>`,94)])])}const q=o(n,[["render",e]]);export{h as __pageData,q as default};
